/* One component, two shapes. Everything the two shared — the tones, the value's
 * tabular figures, the transition — is written once; what differs is only the
 * geometry of the track. */
.progress { --pct: 0; }

/* ── Bar ─────────────────────────────────────────────────────────────────── */
.progress[data-shape='bar'] {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  inline-size: 100%;
}
.progress-labelrow {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--space-3);
  font-size: var(--font-sm);
}
.progress-label { color: var(--foreground); }

.progress-track {
  position: relative;
  inline-size: 100%;
  block-size: var(--space-2);
  border-radius: var(--radius-full);
  background: var(--muted);
  overflow: hidden;
}
.progress-fill {
  inline-size: calc(var(--pct) * 1%);
  block-size: 100%;
  border-radius: inherit;
  background: var(--primary);
  transition: inline-size var(--duration-normal);
}
.progress-track[data-tone='success'] .progress-fill { background: var(--success); }
.progress-track[data-tone='warning'] .progress-fill { background: var(--warning); }
.progress-track[data-tone='danger'] .progress-fill { background: var(--destructive); }

/* Indeterminate: a short segment sliding left to right. A ring has no such
 * form — a circle that never fills reads as broken, not as busy. */
.progress-track[data-indeterminate] .progress-fill {
  inline-size: 35%;
  animation: progress-slide 1.2s ease-in-out infinite;
}
@keyframes progress-slide {
  0%   { transform: translateX(-120%); }
  100% { transform: translateX(320%); }
}

/* ── Ring ────────────────────────────────────────────────────────────────── */
.progress[data-shape='ring'] {
  /* Diameter is a component-private knob; the stroke scales with the viewBox,
   * so one number sizes everything. */
  --progress-ring-size: 3rem;
  display: inline-grid;
  place-items: center;
}
.progress[data-shape='ring'][data-size='sm'] { --progress-ring-size: 2.25rem; }
.progress[data-shape='ring'][data-size='lg'] { --progress-ring-size: 4rem; }

.progress-ring,
.progress[data-shape='ring'] .progress-value { grid-area: 1 / 1; }

.progress-ring {
  inline-size: var(--progress-ring-size);
  block-size: var(--progress-ring-size);
  /* Start at 12 o'clock; the dash itself runs clockwise. */
  transform: rotate(-90deg);
}
.progress-ring-track,
.progress-ring-fill {
  fill: none;
  stroke-width: 3.5;
}
.progress-ring-track { stroke: var(--accent); }
.progress-ring-fill {
  stroke: var(--primary);
  stroke-linecap: round;
  stroke-dasharray: var(--pct) 100;
  transition: stroke-dasharray var(--duration-normal);
}
.progress[data-shape='ring'][data-tone='success'] .progress-ring-fill { stroke: var(--success); }
.progress[data-shape='ring'][data-tone='warning'] .progress-ring-fill { stroke: var(--warning); }
.progress[data-shape='ring'][data-tone='danger'] .progress-ring-fill { stroke: var(--destructive); }

/* ── The value, whichever shape it sits in ───────────────────────────────── */
.progress-value {
  color: var(--muted-foreground);
  font-variant-numeric: tabular-nums;
}
.progress[data-shape='ring'] .progress-value {
  font-size: var(--font-xs);
  font-weight: var(--font-weight-semibold);
  color: var(--foreground);
}
.progress[data-shape='ring'][data-size='lg'] .progress-value { font-size: var(--font-sm); }

import './Progress.css'
import { cn } from '../lib/cn'

type Tone = 'primary' | 'success' | 'warning' | 'danger'
type Size = 'sm' | 'md' | 'lg'

/* Monolithic because it is one measure drawn two ways (bar or ring), and
 * every prop past the value says how that one drawing reads: the tone, the
 * size, and whether the number is written and in whose words. */
type Props = {
  /** 0..max filled fraction. Omit for an INDETERMINATE bar (unknown duration); a ring has no indeterminate form. */
  value?: number
  max?: number
  /** Linear or a ring. A shape, not a meaning — both say the same thing about the same value. */
  shape?: 'bar' | 'ring'
  /** What finishing would MEAN: `primary` for ordinary work, `success` when the bar reaching the
   *  end is the good outcome, `warning` and `danger` when it is a budget or a quota being used
   *  up.
   */
  tone?: Tone
  /** Ring only: how big the ring is. A bar takes the width it is given. */
  size?: Size
  /** Accessible name of what is progressing. */
  label: string
  /** Show the value — beside the label on a bar, inside the ring. */
  showValue?: boolean
  /** Formats the shown value (default is the rounded percentage). */
  /* One argument, like the two sliders that publish the same name: the caller
   * passed `max` in and already has it. (2026-09-03) */
  formatValue?: (value: number) => string
  className?: string
}

const clamp = (n: number) => Math.max(0, Math.min(100, n))

/**
 * How far along something is — as a bar or as a ring.
 *
 * One component, because a bar and a ring are one statement in two shapes:
 * HTML makes the meaningful split elsewhere, between `<progress>` (work moving
 * toward done) and `<meter>` (a value on a scale that does not move), and this
 * system keeps that split as <Progress> and <Meter>. Line versus circle is a
 * choice about the room available, not about what is being said, so it is a
 * prop (2026-08-25; it was two components, and the ring's own description
 * called itself the counterpart of the bar).
 *
 * With `value` it is determinate; without, a bar slides for "working, duration
 * unknown". For a spinning busy marker use <Spinner>; for a gauge with a target
 * use <Meter>.
 *
 * Copy: the label says what is progressing and toward what — "Uploading 3 of 12
 * files". A bare percentage is a number with no subject.
 */
export function Progress({
  value, max = 100, shape = 'bar', tone = 'primary', size, label, showValue, formatValue, className,
}: Props) {
  const indeterminate = value === undefined
  const pct = indeterminate ? 0 : clamp((value / max) * 100)
  const shown = formatValue && !indeterminate ? formatValue(value) : `${Math.round(pct)}%`
  const aria = {
    role: 'progressbar' as const,
    'aria-label': label,
    'aria-valuemin': indeterminate ? undefined : 0,
    'aria-valuemax': indeterminate ? undefined : max,
    'aria-valuenow': indeterminate ? undefined : value,
  }

  /* The ring is drawn with pathLength=100 so the dash pattern speaks in percent;
     `--pct` is the only dynamic style either shape carries. */
  if (shape === 'ring') {
    return (
      <div
        className={cn('progress', className)}
        data-shape="ring"
        data-tone={tone}
        data-size={size}
        style={{ ['--pct' as string]: pct }}
        {...aria}
      >
        <svg className="progress-ring" viewBox="0 0 36 36" aria-hidden="true">
          <circle className="progress-ring-track" cx="18" cy="18" r="16" pathLength="100" />
          <circle className="progress-ring-fill" cx="18" cy="18" r="16" pathLength="100" />
        </svg>
        {showValue && <span className="progress-value" aria-hidden="true">{shown}</span>}
      </div>
    )
  }

  return (
    <div className={cn('progress', className)} data-shape="bar">
      <div className="progress-labelrow">
        <span className="progress-label">{label}</span>
        {showValue && !indeterminate && <span className="progress-value" aria-hidden="true">{shown}</span>}
      </div>
      <div
        className="progress-track"
        data-tone={tone}
        data-indeterminate={indeterminate || undefined}
        style={indeterminate ? undefined : { ['--pct' as string]: pct }}
        {...aria}
      >
        <div className="progress-fill" />
      </div>
    </div>
  )
}
